class Solution {
public:
    int snakesAndLadders(vector<vector<int>>& board) {
        int n = board.size();
        auto getCoords = [&](int s) -> pair<int, int> {
            int quot = (s - 1) / n;
            int rem = (s - 1) % n;
            int r = n - 1 - quot;
            int c = (quot % 2 == 0) ? rem : n - 1 - rem;
            return {r, c};
        };
        vector<int> dist(n * n + 1, -1);
        dist[1] = 0;
        queue<int> q;
        q.push(1);
        while (!q.empty()) {
            int curr = q.front();
            q.pop();
            if (curr == n * n) return dist[curr];
            for (int nxt = curr + 1; nxt <= min(curr + 6, n * n); nxt++) {
                auto [r, c] = getCoords(nxt);
                int dest = (board[r][c] != -1) ? board[r][c] : nxt;
                if (dist[dest] == -1) {
                    dist[dest] = dist[curr] + 1;
                    q.push(dest);
                }
            }
        }
        return -1;
    }
};

class Solution {
    public int snakesAndLadders(int[][] board) {
        int n = board.length;
        int[] dist = new int[n * n + 1];
        Arrays.fill(dist, -1);
        dist[1] = 0;
        Queue<Integer> q = new LinkedList<>();
        q.offer(1);
        while (!q.isEmpty()) {
            int curr = q.poll();
            if (curr == n * n) return dist[curr];
            for (int nxt = curr + 1; nxt <= Math.min(curr + 6, n * n); nxt++) {
                int quot = (nxt - 1) / n;
                int rem = (nxt - 1) % n;
                int r = n - 1 - quot;
                int c = (quot % 2 == 0) ? rem : n - 1 - rem;
                int dest = (board[r][c] != -1) ? board[r][c] : nxt;
                if (dist[dest] == -1) {
                    dist[dest] = dist[curr] + 1;
                    q.offer(dest);
                }
            }
        }
        return -1;
    }
}

var snakesAndLadders = function(board) {
    const n = board.length;
    function getCoords(s) {
        const quot = Math.floor((s - 1) / n);
        const rem = (s - 1) % n;
        const r = n - 1 - quot;
        const c = (quot % 2 === 0) ? rem : n - 1 - rem;
        return [r, c];
    }
    const dist = new Array(n * n + 1).fill(-1);
    dist[1] = 0;
    const q = [1];
    while (q.length > 0) {
        const curr = q.shift();
        if (curr === n * n) return dist[curr];
        for (let nxt = curr + 1; nxt <= Math.min(curr + 6, n * n); nxt++) {
            const [r, c] = getCoords(nxt);
            const dest = board[r][c] !== -1 ? board[r][c] : nxt;
            if (dist[dest] === -1) {
                dist[dest] = dist[curr] + 1;
                q.push(dest);
            }
        }
    }
    return -1;
};
